import java.util.*;
public class Solution {static class E{int to,w;E(int t,int w){to=t;this.w=w;}}static class S{int n,u;long d;S(int n,int u,long d){this.n=n;this.u=u;this.d=d;}}public static long cheapestTrip(int n,int[][] es){if(n==0)return -1;List<List<E>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new ArrayList<>());for(int[] e:es)g.get(e[0]).add(new E(e[1],e[2]));long I=Long.MAX_VALUE/4;long[][] d=new long[n][2];for(long[] r:d)Arrays.fill(r,I);d[0][0]=0;PriorityQueue<S> q=new PriorityQueue<>(Comparator.comparingLong(x->x.d));q.offer(new S(0,0,0));while(!q.isEmpty()){S c=q.poll();if(c.d!=d[c.n][c.u])continue;for(E e:g.get(c.n)){long nd=c.d+e.w;if(nd<d[e.to][c.u]){d[e.to][c.u]=nd;q.offer(new S(e.to,c.u,nd));}if(c.u==0){nd=c.d+e.w/2;if(nd<d[e.to][1]){d[e.to][1]=nd;q.offer(new S(e.to,1,nd));}}}}long a=Math.min(d[n-1][0],d[n-1][1]);return a==I?-1:a;}}
